A, B, X, Y, K=list(map(int,input().split()))

def digsum(x):
	r=0
	while x>0:
		r+=x%10
		x/=10
	return r	
	#return sum(map(int,str(x)))

def simpleCount(l,r):
	if r<=l: return 0
	cnt=0
	incr=0
	if l%K: incr=K-l%K

	for x in range(l+incr,r,K):
		s=digsum(x)
		if X<=s<=Y:cnt+=1
	return cnt
if K>1.e5 or B-A<=2000000:
	print(simpleCount(A,B+1))	
	exit()

FAC=1000000
maxDIGSUM=6*9+1
B+=1

mods=[[0]*K for i in range(maxDIGSUM)]
for i in range(FAC):
	mods[digsum(i)][i%K]+=1

for i in range(1,maxDIGSUM):
	for j in range(K):
		mods[i][j]+=mods[i-1][j]

res=0
last =A-(A%FAC)+FAC;
#assert last%FAC==0
res=simpleCount(A,last)
first=B-(B %FAC)
res+=simpleCount(first,B)
