i=(last/FAC)%10
for x in range(last,first,FAC):
	m=x%K
	if m==0: m=K
	if i%10:
		su=su+1
	else:
		if i%100:
			su=su-8
		else:	
			if i%10000:
				if i%1000:
					su=su-17
